#include "native.h"
static int failures,checks;static void check(int ok,const char*name){checks++;if(!ok){failures++;printf("FAIL %s\n",name);}else printf("PASS %s\n",name);}
static char *key(const char*id){J*a=cJSON_CreateArray();cJSON_AddItemToArray(a,cJSON_CreateString("tasks"));cJSON_AddItemToArray(a,cJSON_CreateString(id));char*k=json(a);cJSON_Delete(a);return k;}
static J *event(const char*k,const char*actor,int seq,int clock,J*ctx,const char*field,const char*value){J*e=cJSON_CreateObject();ss(e,"key",k);ss(e,"actor",actor);sn(e,"seq",seq);sn(e,"clock",clock);set(e,"context",ctx?dup(ctx):cJSON_CreateObject());J*v=cJSON_CreateObject();ss(v,field,value);set(e,"values",v);return e;}
int selftest(const wchar_t*dir){DB d;checks=failures=0;check(db_open(&d,dir),"open isolated database");if(!d.sql)return 1;J*t=task_default(&d,0,0);ss(t,"title","原生中文任务");ss(t,"start","2026-01-31T09:00");char*k=key(str(t,"id"));check(db_edit_data(&d,k,0,t,0),"create task transaction and outbox");J*r=db_row(&d,k);check(r&&!strcmp(str(get(r,"data"),"title"),"原生中文任务"),"Unicode persistence");J*m=db_meta(&d);J*context=dup(get(m,"vector"));cJSON_Delete(m);J*events=cJSON_CreateArray();J*e=event(k,"remote-device",1,9,context,"notes","远端备注");cJSON_AddItemToArray(events,e);check(db_remote(&d,events,"remote-device",1),"apply remote with cursor");check(db_remote(&d,events,"remote-device",1),"duplicate remote replay");J*invalid=event(k,"bad/device",2,10,0,"title","bad");cJSON_AddItemToArray(events,invalid);check(!db_remote(&d,events,"remote-device",2),"invalid batch rolls back");m=db_meta(&d);check(num(get(m,"cursors"),"remote-device")==1,"failed batch cursor unchanged");cJSON_Delete(m);cJSON_Delete(events);cJSON_Delete(r);r=db_row(&d,k);J*before=dup(get(r,"data")),*after=dup(before);ss(after,"title","本地并发标题");check(db_edit_data(&d,k,before,after,context),"causal local edit");events=cJSON_CreateArray();e=event(k,"other-device",1,12,context,"title","远端并发标题");cJSON_AddItemToArray(events,e);check(db_remote(&d,events,"other-device",1),"merge concurrent same field");cJSON_Delete(events);cJSON_Delete(r);r=db_row(&d,k);check(cJSON_GetArraySize(get(r,"conflicts"))==1,"preserve field conflict");cJSON_Delete(before);cJSON_Delete(after);before=dup(get(r,"data"));after=dup(before);ss(after,"title","最终标题");check(db_edit_data(&d,k,before,after,0),"resolve conflict with full vector");cJSON_Delete(r);r=db_row(&d,k);check(cJSON_GetArraySize(get(r,"conflicts"))==0,"resolution removes conflict");cJSON_Delete(before);cJSON_Delete(after);before=dup(get(r,"data"));after=dup(before);J*repeat=cJSON_CreateObject();ss(repeat,"frequency","monthly");sn(repeat,"interval",1);ss(repeat,"anchor","2026-01-31T09:00");ss(repeat,"until","");set(repeat,"weekdays",cJSON_CreateArray());set(after,"repeat",repeat);check(db_edit_data(&d,k,before,after,0),"configure monthly repeat");int count=db_count(&d,"tasks");check(task_complete(&d,k,1),"complete repeating task");check(db_count(&d,"tasks")==count+1,"generate exactly one next instance");check(task_complete(&d,k,1),"repeat completion is idempotent");check(db_count(&d,"tasks")==count+1,"no duplicate recurrence");sqlite3_stmt*q;sqlite3_prepare_v2(d.sql,"SELECT start FROM entities WHERE json_extract(data,'$.generatedFrom')=?",-1,&q,0);sqlite3_bind_text(q,1,str(t,"id"),-1,SQLITE_TRANSIENT);check(sqlite3_step(q)==SQLITE_ROW&&!strcmp((char*)sqlite3_column_text(q,0),"2026-02-28T09:00"),"January 31 clamps to February 28");sqlite3_finalize(q);sqlite3_prepare_v2(d.sql,"SELECT key FROM entities WHERE json_extract(data,'$.generatedFrom')=?",-1,&q,0);sqlite3_bind_text(q,1,str(t,"id"),-1,SQLITE_TRANSIENT);char nextkey[1000]="";if(sqlite3_step(q)==SQLITE_ROW)strcpy(nextkey,(char*)sqlite3_column_text(q,0));sqlite3_finalize(q);check(*nextkey&&task_complete(&d,nextkey,1),"complete February recurrence");J*nextrow=db_row(&d,nextkey);sqlite3_prepare_v2(d.sql,"SELECT start FROM entities WHERE json_extract(data,'$.generatedFrom')=?",-1,&q,0);sqlite3_bind_text(q,1,str(get(nextrow,"data"),"id"),-1,SQLITE_TRANSIENT);check(sqlite3_step(q)==SQLITE_ROW&&!strcmp((char*)sqlite3_column_text(q,0),"2026-03-31T09:00"),"monthly anchor does not drift");sqlite3_finalize(q);cJSON_Delete(nextrow);J*child=task_default(&d,1,str(t,"id"));ss(child,"title","子任务");char*ck=key(str(child,"id"));check(db_edit_data(&d,ck,0,child,0),"create nested task");check(task_delete(&d,k),"delete parent and descendants");J*cr=db_row(&d,ck);check(truth(cr,"deleted"),"descendant tombstone retained");cJSON_Delete(cr);events=cJSON_CreateArray();e=event(k,"offline-device",1,90,0,"notes","删除前离线内容");cJSON_AddItemToArray(events,e);check(db_remote(&d,events,"offline-device",1),"late offline edit applied safely");cJSON_Delete(events);cJSON_Delete(r);r=db_row(&d,k);check(truth(r,"deleted"),"late edit does not resurrect");check(db_check(&d),"SQLite integrity");J*out=db_outbox(&d,500);check(cJSON_GetArraySize(out)>5,"outbox durable");cJSON_Delete(out);db_close(&d);check(db_open(&d,dir),"reopen database");cr=db_row(&d,k);check(truth(cr,"deleted"),"tombstone survives restart");cJSON_Delete(cr);check(time_ms("2026-02-30T10:00")==-1,"invalid calendar date rejected");check(time_ms("2026-10-21T09:00")>=0,"Beijing date parsing");J*number=cJSON_CreateObject();sn(number,"order",77824.00147002262);char*numberText=json(number);J*parsed=cJSON_Parse(numberText);check(num(parsed,"order")==77824.00147002262,"double precision roundtrip");free(numberText);cJSON_Delete(parsed);cJSON_Delete(number);cJSON_Delete(t);cJSON_Delete(child);cJSON_Delete(r);cJSON_Delete(before);cJSON_Delete(after);cJSON_Delete(context);free(k);free(ck);db_close(&d);printf("{\"checks\":%d,\"failures\":%d}\n",checks,failures);return failures?1:0;}
